namespace ghidra.app.plugin.core.compositeeditor;



using docking;
using docking;
using docking.action;
using docking.action;
using docking.menu;

/**
 * Action for use in the composite data type editor.
 * This action has help associated with it.
 */
public class HexNumbersAction : CompositeEditorTableAction, ToggleDockingActionIf {

	public static string ACTION_NAME = "Show Numbers In Hex";
	private static string GROUP_NAME = DATA_ACTION_GROUP;
	private static string DESCRIPTION = "Show Numbers in Hexadecimal";
	private static string[] PATH = new string[] { DESCRIPTION };
	private bool isSelected;

	public HexNumbersAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, PATH, PATH, null)
    {
		setDescription(DESCRIPTION);
		setSelected(model.isShowingNumbersInHex());
		setKeyBindingData(new KeyBindingData("Shift-H"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		model.displayNumbersInHex(!model.isShowingNumbersInHex());
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry();
	}

	/* @Override */
	public bool isSelected() {
		return isSelected;
	}

	/* @Override */
	public void setSelected(bool newValue) {
		if (isSelected == newValue) {
			return;
		}
		isSelected = newValue;
		firePropertyChanged(SELECTED_STATE_PROPERTY, !isSelected, isSelected);
	}

	/* @Override */
	protected JMenuItem doCreateMenuItem() {
		DockingCheckBoxMenuItem menuItem = new DockingCheckBoxMenuItem(isSelected);
		menuItem.setUI(DockingCheckboxMenuItemUI.createUI(menuItem));
		return menuItem;
	}
}
